    const float* Asrc_b = Asrc + (long)bid * strideHb + (long)j * strideHn + jb; // (j..,jb..)
    float* Hb = Hbuf + (long)bid * strideHb + (long)j * strideHn + jb;           // dst strip top-left
    const float* Vb = Vbuf + (long)bid * strideVb;     // Vt[k,r]
    const float* Tb = Tbuf + (long)bid * strideTb;

    // ---- load A strip into smem (col-major sCs[r + c*PHpad]); pad rows>=pheight
    // and cols>=ncols with 0 so WMMA frags over the padded tile are exact. ----
    for (long idx = tid; idx < (long)PHpad * BNc; idx += nthr) {
        int r = idx % PHpad;            // 0..PHpad-1
        int c = idx / PHpad;            // 0..BNc-1
        int gc = c0 + c;                // global trailing column offset
        float v = 0.0f;
        if (r < pheight && gc < ncols)
            v = Asrc_b[(long)r * strideHn + gc];
        sCs[idx] = v;
    }
    __syncthreads();

    // ===== Step 1: W[BLK x BNc] = V^T @ Cs  (M=BLK, N=BNc, K=pheight) =====
    // A = V^T : (BLK x pheight) row-major. Vbuf is indexed by RELATIVE panel row
    //   r in [0,pheight) (NO j offset -- _panel_factor_kernel stores Vt[k,r_rel] at
    //   Vb[k*strideVk + r_rel*strideVn]); V[r,k]=Vt[k,r] so V^T[k,r]=Vt[k,r]=
    //   Vb[k*strideVk + r*strideVn]. WMMA row_major frag A[k,r] wants ldm = stride
    //   between consecutive ROWS (k) = strideVk, elements within a row step strideVn
    //   (==1, Vbuf contiguous in N). OK.
    // B = Cs : (pheight x BNc) col-major in smem, ldm = PHpad.
    // W stored col-major in sW (ldm BLK): W[i,g] at sW[i + g*BLK].
    {
        const float* Vt_blk = Vb;   // V^T[k,r] = Vt_blk[k*strideVk + r*strideVn]
        int mt = BLK / 16;        // m-tiles (output rows = BLK)
        int nt = BNc / 16;        // n-tiles (output cols = BNc)
        int kt = PHpad / 8;       // k-tiles over padded rows
        int ntiles = mt * nt;
        for (int tile = warp; tile < ntiles; tile += WB) {
            int mi = tile / nt;
            int ni = tile % nt;
            RFragAcc acc; wmma::fill_fragment(acc, 0.0f);
            for (int kk = 0; kk < kt; ++kk) {
                // A frag: rows [mi*16, +16) of V^T, cols [kk*8,+8) -> Vt_blk + mi*16*strideVk + kk*8*strideVn
                RFragAR a; wmma::load_matrix_sync(a, Vt_blk + (long)mi * 16 * strideVk + (long)kk * 8 * strideVn, strideVk);
                // B frag: rows [kk*8,+8) of Cs, cols [ni*16,+16) -> sCs + kk*8 + ni*16*PHpad, col-major ldm PHpad
                RFragBC b; wmma::load_matrix_sync(b, sCs + (long)kk * 8 + (long)ni * 16 * PHpad, PHpad);
                RFragAR ah, al; RFragBC bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
                wmma::mma_sync(acc, ah, bh, acc);
                wmma::mma_sync(acc, ah, bl, acc);
                wmma::mma_sync(acc, al, bh, acc);
            }
            wmma::store_matrix_sync(sW + (long)mi * 16 + (long)ni * 16 * BLK, acc, BLK, wmma::mem_col_major);
        }
    }
    __syncthreads();

    // ===== Step 2: W''[i,g] = -sum_{l<=i} T[l,i] W[l,g]  (SIMT, negated) =====
    // Negate so step 3 folds the subtract into the preloaded accumulator.
    // sW holds W; write W'' to the same buffer is unsafe (in-place read/write
    // across threads) -> write W'' into the second half? We reuse sW by computing
    // all of W'' into registers per element from W still in sW, but a thread g,i
    // reads W[l,g] for l<=i (other rows, same col) which are NOT being overwritten
    // by this thread -> race only if another thread overwrote sW[l,g]. Each (i,g)
    // is one thread; thread (i,g) writes sW[i,g]. Thread (i2>i,g) reads sW[i,g]
    // (l=i<=i2). RACE. So stage W'' in a separate region: reuse sCs tail? No.
    // Simpler: each thread computes its W'' into a register, __syncthreads, then
    // all write. Use a tiny second smem buffer right after sW.
    float* sWpp = sW + (long)BLK * BNc;   // BLK * BNc  (W'')
    for (int idx = tid; idx < BLK * BNc; idx += nthr) {
        int g = idx / BLK, i = idx % BLK;
        float a = 0.f;
        for (int l = 0; l <= i; ++l)
            a += Tb[(long)l * strideTk + (long)i * strideTn] * sW[(long)l + (long)g * BLK];
        sWpp[(long)i + (long)g * BLK] = -a;
    }
    __syncthreads();

    // ===== Step 3: Cs += V @ W''  (== Cs - V @ (T^T W)) =====
    // A = V : (pheight x BLK) col-major. V[r,k]=Vt[k,r]=Vt_blk[k*strideVk+r*strideVn]
    //   (relative row r, no j offset). WMMA col_major frag A[r,k] wants ldm = stride
    //   between consecutive COLS (k) = strideVk; within a col (r) step strideVn. OK.
    // B = W'' : (BLK x BNc) col-major in sWpp, ldm BLK.
    // Preload current Cs tile into acc so the store writes Cs_new; then store to smem.
    {
        const float* Vt_blk = Vb;
        int mt = PHpad / 16;      // row tiles over padded pheight
        int nt = BNc / 16;
        int kt = BLK / 8;         // k over BLK
        int ntiles = mt * nt;
        for (int tile = warp; tile < ntiles; tile += WB) {
            int mi = tile / nt;
            int ni = tile % nt;
            RFragAcc acc;
            // acc = current Cs tile (smem, col-major ldm PHpad)
            wmma::load_matrix_sync(acc, sCs + (long)mi * 16 + (long)ni * 16 * PHpad, PHpad, wmma::mem_col_major);
            for (int kk = 0; kk < kt; ++kk) {
                int kb = kk * 8;
                RFragAC a; wmma::load_matrix_sync(a, Vt_blk + (long)mi * 16 * strideVn + (long)kb * strideVk, strideVk);
                RFragBC b; wmma::load_matrix_sync(b, sWpp + kb + (long)ni * 16 * BLK, BLK);
                RFragAC ah, al; RFragBC bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
                wmma::mma_sync(acc, ah, bh, acc);
                wmma::mma_sync(acc, ah, bl, acc);
                wmma::mma_sync(acc, al, bh, acc);
            }
            wmma::store_matrix_sync(sCs + (long)mi * 16 + (long)ni * 16 * PHpad, acc, PHpad, wmma::mem_col_major);
        }
    }
    __syncthreads();

    // ---- write the resident strip back to H (only valid rows/cols) ----
    for (long idx = tid; idx < (long)PHpad * BNc; idx += nthr) {
        int r = idx % PHpad;
        int c = idx / PHpad;
        int gc = c0 + c;
        if (r < pheight && gc < ncols)
            Hb[(long)r * strideHn + gc] = sCs[idx];
    }
}


