#include <mma.h>
using namespace nvcuda;

typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> RFragAR;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::col_major> RFragBC;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> RFragAcc;

// ===========================================================================
// wred_splitk_partial: hand-CUDA WMMA tf32x3 SPLIT-K partial of W = V^T @ A_trail.
// grid = (col_tiles, S, B). CTA (ct, s, b) reduces A rows [s*Kslice, (s+1)*Kslice)
// for matrix b, output partial Wpart[b, s, BLK, ncols] tile [:, c0:c0+BNc].
//
// Each CTA stages its (Kslice x BNc) A-chunk in smem (col-major, padded rows to
// mult of 16), loads V^T[BLK x Kslice] frags from global, and does WMMA
// M=BLK,N=BNc,K=Kslice into an accumulator -> stores the partial.
//
// This is the brief's split-K W-reduction microkernel: S CTAs per col-tile per
// matrix each do a SHORT (K/S) reduction (S independent WMMA tiles = fills idle
// warps), vs the fused kernel's ONE CTA doing the full deep-K serial accumulate.
// Register/smem hand-budgeted so occupancy does not collapse (BNc small, only the
// Kslice-chunk resident not the whole strip).
// ===========================================================================
extern "C" __global__ void wred_splitk_partial(
    const float* __restrict__ A,      // (B, N, N) row-major
    const float* __restrict__ Vbuf,   // (B, BLK, N) Vt[k,r] (relative row r)
    float* __restrict__ Wpart,        // (B, S, BLK, ncols_pad) col-major-ish: [b,s, i + g*BLK]
    int B, int N, int j, int pheight, int ncols, int jb, int S, int Kslice,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    long strideWb, long strideWs,     // Wpart strides for b, s ; tile is BLK x ncols col-major (i + g*BLK)
    int BLK, int BNc, int KSpad)      // KSpad = Kslice rounded up to mult of 16
{
    const int col_tile = blockIdx.x;
    const int sl       = blockIdx.y;
    const int bid      = blockIdx.z;
    if (bid >= B) return;
    const int c0 = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int WB = nthr >> 5;

    const int r_start = sl * Kslice;
    int r_end = r_start + Kslice;
    if (r_end > pheight) r_end = pheight;
    const int rows = r_end - r_start;       // actual rows this slice (<=Kslice)
    if (rows <= 0) return;

    extern __shared__ float smem[];
    float* sA = smem;                        // KSpad * BNc col-major (ldm KSpad)

    const float* Ab = A + (long)bid * strideAb + (long)(j + r_start) * strideAn + jb;
    const float* Vb = Vbuf + (long)bid * strideVb;   // Vt[k, r] ; r is relative panel row

    // load A chunk -> smem (col-major sA[r + c*KSpad]); pad rows>=rows, cols>=valid with 0
    for (long idx = tid; idx < (long)KSpad * BNc; idx += nthr) {
        int r = idx % KSpad;
        int c = idx / KSpad;
        int gc = c0 + c;
        float v = 0.0f;
        if (r < rows && gc < ncols)
            v = Ab[(long)r * strideAn + gc];
        sA[idx] = v;
    }
    __syncthreads();

    // W tile = V^T @ A_chunk : M=BLK, N=BNc, K=KSpad. A frag = V^T[k, r_rel]
    // (row_major ldm strideVk). V^T row k = reflector k, col r = relative panel
    // row (r_start + local). So the global panel row for this slice's local row rr
    // is (r_start + rr); V^T[k, r_start+rr] = Vb[k*strideVk + (r_start+rr)*strideVn].
    int mt = BLK / 16;
    int nt = BNc / 16;
    int kt = KSpad / 8;
    int ntiles = mt * nt;
    const float* Vt_slice = Vb + (long)r_start * strideVn;   // V^T[:, r_start..]
    for (int tile = warp; tile < ntiles; tile += WB) {
        int mi = tile / nt;
        int ni = tile % nt;
        RFragAcc acc; wmma::fill_fragment(acc, 0.0f);
        for (int kk = 0; kk < kt; ++kk) {
            RFragAR a; wmma::load_matrix_sync(a, Vt_slice + (long)mi * 16 * strideVk + (long)kk * 8 * strideVn, strideVk);
            RFragBC b; wmma::load_matrix_sync(b, sA + (long)kk * 8 + (long)ni * 16 * KSpad, KSpad);
            RFragAR ah, al; RFragBC bh, bl;
            #pragma unroll
            for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
            #pragma unroll
            for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
            wmma::mma_sync(acc, ah, bh, acc);
            wmma::mma_sync(acc, ah, bl, acc);
            wmma::mma_sync(acc, al, bh, acc);
        }
        // store partial W tile [mi*16:+16, c0+ni*16:+16] col-major into Wpart[b,s]
        float* Wt = Wpart + (long)bid * strideWb + (long)sl * strideWs;  // BLK x ncols, i + g*BLK
        wmma::store_matrix_sync(Wt + (long)mi * 16 + (long)(c0 + ni * 16) * BLK, acc, BLK, wmma::mem_col_major);
    }
}

// ===========================================================================
// wred_finish: sum S partials -> W (BLK x ncols). grid=(ncols_tiles, B). SIMT.
// ===========================================================================
extern "C" __global__ void wred_finish(
    const float* __restrict__ Wpart,  // (B, S, BLK, ncols) col-major tiles (i+g*BLK)
    float* __restrict__ Wout,         // (B, BLK, ncols) col-major (i+g*BLK)
    int B, int ncols, int S,
    long strideWb, long strideWs,
    long strideWob,
    int BLK, int BNc)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int c0 = col_tile * BNc;
    for (int idx = tid; idx < BLK * BNc; idx += nthr) {
        int i = idx % BLK;
        int cc = idx / BLK;
        int g = c0 + cc;
        if (g >= ncols) continue;
        float acc = 0.0f;
        const float* Wp = Wpart + (long)bid * strideWb;
        for (int s = 0; s < S; ++s)
            acc += Wp[(long)s * strideWs + (long)i + (long)g * BLK];
        Wout[(long)bid * strideWob + (long)i + (long)g * BLK] = acc;
    }
}

