#include <mma.h>
using namespace nvcuda;

typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> RFragAR;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::col_major> RFragBC;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> RFragAcc;

// ===========================================================================
// wred_splitk_partial2: REGISTER/SMEM-BUDGETED split-K W = V^T @ A_trail.
// grid=(col_tiles, S, B), block=nthr. Stage V^T[BLK x Kslice] in SMEM (small for
// large S: BLK*KSpad*4 bytes), load A_trail fragments DIRECTLY from global
// (A is row-major; the B-fragment of A_trail is col_major over (K rows x BNc cols),
// loaded via load_matrix_sync with ldm=strideAn so it reads coalesced-ish columns).
// Tiny smem -> occupancy survives (the brief's "hand-budget so occupancy does not
// collapse"). Each warp owns output tiles (BLK/16 x BNc/16) round-robin.
//
// A_trail B-fragment: WMMA wants matrix_b col_major frag B[k, n] with ldm = stride
// between consecutive COLUMNS (n). A_trail[k_global_row, n_col] is at
// A[(j+r_start+k)*strideAn + (jb+c0+n)] with consecutive n contiguous (stride 1) and
// consecutive k strided by strideAn. col_major frag B[k,n]: rows=k (within-col step),
// cols=n. ldm = stride between cols = 1?? No: col_major ldm = leading dim = #rows
// stored contiguously = stride to next column. For A_trail laid (k rows, n cols) with
// n contiguous, to view it col_major (each column k-contiguous) we'd need k contiguous
// -> it's NOT. So load A as matrix_b ROW_major instead: B is (K x N), row_major ldm =
// strideAn (consecutive rows strided strideAn, consecutive cols stride 1). Use a
// matrix_b row_major fragment. (mma_sync supports a row_major B too.)
// ===========================================================================
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> RFragBR;

extern "C" __global__ void wred_splitk_partial2(
    const float* __restrict__ A,      // (B, N, N) row-major
    const float* __restrict__ Vbuf,   // (B, BLK, N) Vt[k,r]
    float* __restrict__ Wpart,        // (B, S, BLK*ncols) col-major tile (i + g*BLK)
    int B, int N, int j, int pheight, int ncols, int jb, int S, int Kslice,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    long strideWb, long strideWs,
    int BLK, int BNc, int KSpad)
{
    const int col_tile = blockIdx.x;
    const int sl       = blockIdx.y;
    const int bid      = blockIdx.z;
    if (bid >= B) return;
    const int c0 = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int WB = nthr >> 5;

    const int r_start = sl * Kslice;
    int r_end = r_start + Kslice;
    if (r_end > pheight) r_end = pheight;
    const int rows = r_end - r_start;
    if (rows <= 0) return;

    extern __shared__ float smem[];
    float* sV = smem;     // BLK * KSpad  row-major (k-th reflector row, then KSpad cols) : sV[k*KSpad + r]

    const float* Vb = Vbuf + (long)bid * strideVb;
    // load V^T[k, r_rel] for r_rel in [r_start, r_end) into sV[k*KSpad + (r_rel-r_start)]
    for (long idx = tid; idx < (long)BLK * KSpad; idx += nthr) {
        int k = idx / KSpad;
        int rr = idx % KSpad;
        float v = 0.0f;
        if (rr < rows)
            v = Vb[(long)k * strideVk + (long)(r_start + rr) * strideVn];
        sV[idx] = v;
    }
    __syncthreads();

    const float* Ab = A + (long)bid * strideAb + (long)(j + r_start) * strideAn + jb + c0;

    int mt = BLK / 16;
    int nt = BNc / 16;
    int kt = KSpad / 8;
    int ntiles = mt * nt;
    for (int tile = warp; tile < ntiles; tile += WB) {
        int mi = tile / nt;
        int ni = tile % nt;
        RFragAcc acc; wmma::fill_fragment(acc, 0.0f);
        for (int kk = 0; kk < kt; ++kk) {
            // A frag (V^T) from smem sV row_major: rows [mi*16,+16) (reflectors), cols [kk*8,+8) (rel rows). ldm=KSpad.
            RFragAR a; wmma::load_matrix_sync(a, sV + (long)mi * 16 * KSpad + (long)kk * 8, KSpad);
            // B frag (A_trail) from global row_major: rows [kk*8,+8) (rel matrix rows), cols [ni*16,+16) (trail cols). ldm=strideAn.
            RFragBR b; wmma::load_matrix_sync(b, Ab + (long)kk * 8 * strideAn + (long)ni * 16, strideAn);
            RFragAR ah, al; RFragBR bh, bl;
            #pragma unroll
            for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
            #pragma unroll
            for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
            wmma::mma_sync(acc, ah, bh, acc);
            wmma::mma_sync(acc, ah, bl, acc);
            wmma::mma_sync(acc, al, bh, acc);
        }
        // store partial tile masked to valid cols
        float* Wt = Wpart + (long)bid * strideWb + (long)sl * strideWs;
        // store_matrix_sync writes a full 16x16; guard by only storing tiles fully in range,
        // else fall back to elementwise. Here ncols may not be mult of 16 in the last tile.
        int gcol0 = c0 + ni * 16;
        if (gcol0 + 16 <= ncols) {
            wmma::store_matrix_sync(Wt + (long)mi * 16 + (long)gcol0 * BLK, acc, BLK, wmma::mem_col_major);
        } else {
            // partial last tile: store to a tmp then copy valid cols (rare; ncols=480 is mult of 16 so this won't trigger here)
            __shared__ float tmp[16*16];
            wmma::store_matrix_sync(tmp, acc, 16, wmma::mem_col_major);
            for (int e = tid & 31; e < 256; e += 32) {
                int rr = e % 16, cc = e / 16;
                int gc = gcol0 + cc;
                if (gc < ncols)
                    Wt[(long)(mi*16+rr) + (long)gc * BLK] = tmp[rr + cc*16];
            }
        }
    }
}

extern "C" __global__ void wred_finish(
    const float* __restrict__ Wpart,
    float* __restrict__ Wout,
    int B, int ncols, int S,
    long strideWb, long strideWs,
    long strideWob,
    int BLK, int BNc)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int c0 = col_tile * BNc;
    for (int idx = tid; idx < BLK * BNc; idx += nthr) {
        int i = idx % BLK;
        int cc = idx / BLK;
        int g = c0 + cc;
        if (g >= ncols) continue;
        float acc = 0.0f;
        const float* Wp = Wpart + (long)bid * strideWb;
        for (int s = 0; s < S; ++s)
            acc += Wp[(long)s * strideWs + (long)i + (long)g * BLK];
        Wout[(long)bid * strideWob + (long)i + (long)g * BLK] = acc;
    }
}

